const WIDTH = 1080;
const HEIGHT = 1920;
const FPS = 30;
const DEFAULT_DURATION = 225.95;

const NARRATION_TEXT = `Pernahkah kalian berpikir, kenapa sebuah komputer atau laptop bisa menjalankan game berat dengan grafis memukau, sementara perangkat lain langsung lag bahkan saat sekadar membuka beberapa tab browser? Banyak orang mengira kecepatan komputer hanya ditentukan oleh satu komponen saja. Padahal, di balik layar yang menyala itu, ada kerja sama tiga otak utama yang punya tugas sangat spesifik dan gak bisa saling menggantikan. Halo, gue Ilmi. Gue mungkin bukan orang paling jenius di ruangan ini, tapi kalau sudah berhadapan dengan jeroan teknologi, seperti hardware komputer, gue gak akan berhenti membongkar logikanya sampai benar-benar paham cara kerjanya. Dan karena kebiasaan itulah, orang-orang mulai memanggil gue: Profesor Ilmi. Mari kita bedah tiga komponen paling krusial dalam sebuah komputer: prosesor (CPU), RAM, dan VGA (GPU). Untuk memahaminya secara spesifik tanpa terjebak istilah teknis yang membosankan, bayangkan sebuah dapur restoran kelas dunia. Pertama, ada prosesor atau CPU, Central Processing Unit. Di dapur tadi, prosesor adalah kepala koki. Dia yang membaca resep, mengatur strategi, melakukan perhitungan matematika rumit, dan mengeksekusi setiap perintah dari sistem operasi maupun aplikasi. Secara teknis, performa prosesor diukur dari jumlah core, inti pemrosesan, dan clock speed, kecepatan memproses instruksi dalam satuan Gigahertz. Semakin banyak core dan semakin tinggi kecepatannya, semakin cepat kepala koki ini menyelesaikan berbagai tugas logika, mulai dari membuka file, menjalankan kode program, hingga mengatur alur kerja komponen lainnya. Kedua, ada RAM, Random Access Memory. Jika prosesor adalah kepala koki, maka RAM adalah meja kerja di dapur tersebut. Saat koki memasak, dia tidak mungkin bolak-balik mengambil bahan dari kulkas penyimpanan, SSD atau hardisk, setiap detik karena itu akan memakan waktu lama. Jadi, dia menaruh semua bahan yang sedang dipakai di atas meja kerja agar bisa dijangkau secara instan. Secara spesifik, RAM adalah memori penyimpanan sementara yang sangat cepat. Semakin besar kapasitas RAM, misalnya 16 GB dibanding 8 GB, semakin luas meja kerjanya. Artinya, kamu bisa membuka aplikasi editing, puluhan tab browser, dan pemutar musik secara bersamaan, multitasking, tanpa membuat sistem melambat karena meja kerjanya kepenuhan. Ketiga, ada VGA, Video Graphics Array, atau yang kini lebih tepat disebut GPU, Graphics Processing Unit. Di dapur kita, VGA adalah tim seniman dekorasi makanan. Kepala koki sangat pintar dalam logika dan manajemen, tetapi jika disuruh melukis detail piring yang rumit secara cepat, dia akan kewalahan. Di sinilah VGA mengambil alih. VGA memiliki ribuan inti kecil yang dirancang khusus untuk memproses data visual secara paralel, mulai dari merender poligon 3D, menghitung pantulan cahaya (ray tracing), tekstur objek, hingga menampilkan jutaan piksel ke layar monitor dalam hitungan milidetik. Tanpa VGA yang mumpuni, tugas berat seperti bermain game AAA, rendering video 4K, atau pemodelan 3D akan membuat komputer tersendat parah. Singkatnya, prosesor adalah otak yang berpikir dan mengeksekusi perintah, RAM adalah ruang kerja sementara yang menentukan kelancaran multitasking, dan VGA adalah spesialis visual yang menerjemahkan data menjadi gambar tajam di layar. Ketiganya harus seimbang. Percuma punya kepala koki tercepat jika meja kerjanya sempit, atau punya meja luas tapi tidak ada seniman visual untuk mengolah grafis berat. Sekarang teka-teki performa komputer sudah terpecahkan. Sampai jumpa di eksperimen teknologi berikutnya.`;

// ============================================================================
// SAFE COLOR & MATH HELPERS (NO UNCLOSED BACKTICKS)
// ============================================================================
function rgba(r, g, b, a) {
  return "rgba(" + Math.round(r) + "," + Math.round(g) + "," + Math.round(b) + "," + Number(a).toFixed(3) + ")";
}

function clamp(val, min, max) {
  return Math.max(min, Math.min(max, val));
}

function lerp(a, b, t) {
  return a + (b - a) * clamp(t, 0, 1);
}

function easeOutCubic(x) {
  const t = clamp(x, 0, 1);
  return 1 - Math.pow(1 - t, 3);
}

function easeOutBack(x) {
  const t = clamp(x, 0, 1);
  const c1 = 1.70158;
  const c3 = c1 + 1;
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
}

function sceneProgress(t, start, end) {
  return clamp((t - start) / Math.max(0.001, end - start), 0, 1);
}

// ============================================================================
// PALETTE (DARK STUDIO & HIGH-CONTRAST HARDWARE COLORS)
// ============================================================================
const PAL = {
  bgTop: "#0B1120",
  bgMid: "#0F172A",
  bgBot: "#1E293B",
  cardBg: "#162033",
  cardBgAlt: "#1B2840",
  cardBorder: "#334155",
  textMain: "#F8FAFC",
  textSub: "#94A3B8",
  cpuMain: "#F59E0B",
  cpuGlow: "#FBBF24",
  ramMain: "#06B6D4",
  ramGlow: "#38BDF8",
  gpuMain: "#10B981",
  gpuGlow: "#34D399",
  purple: "#8B5CF6",
  danger: "#F43F5E",
  lpgGreen: "#74C647",
  lpgDark: "#4E9A25",
  lpgLight: "#A3E87C",
  lpgRed: "#E11D48",
  brass: "#FBBF24"
};

// ============================================================================
// PRIMITIVE DRAWING HELPERS
// ============================================================================
function roundedRectPath(ctx, x, y, w, h, r) {
  const rad = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rad, y);
  ctx.lineTo(x + w - rad, y);
  ctx.arcTo(x + w, y, x + w, y + rad, rad);
  ctx.lineTo(x + w, y + h - rad);
  ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
  ctx.lineTo(x + rad, y + h);
  ctx.arcTo(x, y + h, x, y + h - rad, rad);
  ctx.lineTo(x, y + rad);
  ctx.arcTo(x, y, x + rad, y, rad);
  ctx.closePath();
}

function fillRoundRect(ctx, x, y, w, h, r, fillStyle, strokeStyle, lineWidth) {
  roundedRectPath(ctx, x, y, w, h, r);
  if (fillStyle) {
    ctx.fillStyle = fillStyle;
    ctx.fill();
  }
  if (strokeStyle) {
    ctx.strokeStyle = strokeStyle;
    ctx.lineWidth = lineWidth || 2;
    ctx.stroke();
  }
}

function drawCard(ctx, x, y, w, h, accentColor, titleBadge) {
  ctx.save();
  fillRoundRect(ctx, x + 4, y + 8, w, h, 28, rgba(2, 6, 23, 0.55), null, 0);
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, "#19253A");
  grad.addColorStop(1, "#111A2B");
  fillRoundRect(ctx, x, y, w, h, 28, grad, accentColor || PAL.cardBorder, 2.5);

  if (accentColor) {
    fillRoundRect(ctx, x + 28, y + 2, w - 56, 5, 2.5, accentColor, null, 0);
  }

  if (titleBadge) {
    ctx.font = "bold 23px sans-serif";
    const tw = ctx.measureText(titleBadge).width;
    const bw = tw + 44;
    fillRoundRect(ctx, x + 28, y + 22, bw, 44, 14, rgba(15, 23, 42, 0.85), accentColor || PAL.cardBorder, 2);
    ctx.fillStyle = accentColor || PAL.textMain;
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    ctx.fillText(titleBadge, x + 50, y + 44);
  }
  ctx.restore();
}

function drawBackground(ctx, t) {
  const grad = ctx.createLinearGradient(0, 0, 0, HEIGHT);
  grad.addColorStop(0, PAL.bgTop);
  grad.addColorStop(0.5, PAL.bgMid);
  grad.addColorStop(1, PAL.bgBot);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  ctx.save();
  ctx.strokeStyle = rgba(148, 163, 184, 0.045);
  ctx.lineWidth = 1;
  const step = 60;
  const offset = (t * 12) % step;
  for (let x = 0; x <= WIDTH; x += step) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, HEIGHT);
    ctx.stroke();
  }
  for (let y = offset; y <= HEIGHT; y += step) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(WIDTH, y);
    ctx.stroke();
  }
  ctx.restore();
}

function drawTopHeader(ctx, stepBadge, mainTitle, accentColor) {
  ctx.save();
  fillRoundRect(ctx, 60, 64, 960, 126, 24, rgba(22, 32, 51, 0.92), accentColor, 2.5);

  ctx.font = "bold 22px sans-serif";
  const bw = ctx.measureText(stepBadge).width + 36;
  fillRoundRect(ctx, 86, 86, bw, 36, 18, accentColor, null, 0);
  ctx.fillStyle = "#0F172A";
  ctx.textAlign = "left";
  ctx.textBaseline = "middle";
  ctx.fillText(stepBadge, 104, 104);

  ctx.fillStyle = PAL.textMain;
  ctx.font = "bold 35px sans-serif";
  ctx.textAlign = "left";
  ctx.textBaseline = "middle";
  ctx.fillText(mainTitle, 86, 152);
  ctx.restore();
}

function drawBottomTimeline(ctx, t, totalDur) {
  const chapters = [
    { label: "INTRO", start: 0, end: 23, col: PAL.ramGlow },
    { label: "PROF. ILMI", start: 23, end: 42, col: PAL.lpgGreen },
    { label: "DAPUR PC", start: 42, end: 58, col: PAL.purple },
    { label: "1. CPU", start: 58, end: 99, col: PAL.cpuMain },
    { label: "2. RAM", start: 99, end: 148, col: PAL.ramMain },
    { label: "3. VGA/GPU", start: 148, end: 196, col: PAL.gpuMain },
    { label: "SINERGI", start: 196, end: 226, col: PAL.lpgGreen }
  ];

  ctx.save();
  const barY = 1785;
  fillRoundRect(ctx, 60, barY, 960, 82, 20, rgba(15, 23, 42, 0.9), "#334155", 2);

  const segW = (960 - 32) / chapters.length;
  for (let i = 0; i < chapters.length; i++) {
    const ch = chapters[i];
    const sx = 76 + i * segW;
    const active = t >= ch.start && t < ch.end;
    const passed = t >= ch.end;

    fillRoundRect(
      ctx,
      sx + 3,
      barY + 12,
      segW - 6,
      36,
      10,
      active ? ch.col : passed ? rgba(51, 65, 85, 0.7) : rgba(30, 41, 59, 0.6),
      active ? "#FFFFFF" : null,
      active ? 1.5 : 0
    );

    ctx.font = active ? "bold 18px sans-serif" : "17px sans-serif";
    ctx.fillStyle = active ? "#0F172A" : passed ? "#CBD5E1" : "#64748B";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(ch.label, sx + segW / 2, barY + 30);
  }

  const prog = clamp(t / totalDur, 0, 1);
  fillRoundRect(ctx, 76, barY + 58, 928, 10, 5, "#1E293B", null, 0);
  fillRoundRect(ctx, 76, barY + 58, Math.max(12, 928 * prog), 10, 5, PAL.lpgGreen, null, 0);
  ctx.restore();
}

// ============================================================================
// STICKMAN WITH 3KG LPG MELON HAT
// ============================================================================
function drawLpgHat(ctx, hx, hy, headRadius, tilt) {
  ctx.save();
  ctx.translate(hx, hy);
  ctx.rotate(tilt || 0);

  const hatY = -headRadius * 1.15;
  const rx = headRadius * 1.38;
  const ry = headRadius * 1.18;

  // 1. Top Red Guard Collar (handle shroud of 3kg LPG cylinder)
  const collarW = rx * 1.1;
  const collarH = ry * 0.55;
  const collarY = hatY - ry - collarH * 0.55;
  fillRoundRect(ctx, -collarW / 2, collarY, collarW, collarH, 6, PAL.lpgRed, "#1E293B", 2.5);

  // Cutout vents in red collar
  fillRoundRect(ctx, -collarW * 0.34, collarY + collarH * 0.25, collarW * 0.24, collarH * 0.36, 3, "#0F172A", null, 0);
  fillRoundRect(ctx, collarW * 0.10, collarY + collarH * 0.25, collarW * 0.24, collarH * 0.36, 3, "#0F172A", null, 0);

  // Brass center valve pin
  fillRoundRect(ctx, -5, collarY + 4, 10, collarH * 0.65, 2, PAL.brass, "#1E293B", 1.5);

  // 2. Plump Green Melon Gas Body
  ctx.beginPath();
  ctx.ellipse(0, hatY, rx, ry, 0, 0, Math.PI * 2);
  const bodyGrad = ctx.createRadialGradient(-rx * 0.3, hatY - ry * 0.3, rx * 0.1, 0, hatY, rx * 1.1);
  bodyGrad.addColorStop(0, PAL.lpgLight);
  bodyGrad.addColorStop(0.55, PAL.lpgGreen);
  bodyGrad.addColorStop(1, PAL.lpgDark);
  ctx.fillStyle = bodyGrad;
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = "#1E293B";
  ctx.stroke();

  // Clip inside melon sphere for stripes & label
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(0, hatY, rx - 1.5, ry - 1.5, 0, 0, Math.PI * 2);
  ctx.clip();

  // Red stripe band
  ctx.fillStyle = PAL.lpgRed;
  ctx.fillRect(-rx, hatY - ry * 0.22, rx * 2, ry * 0.34);

  // Center weld ring line
  ctx.strokeStyle = "#2E5A1C";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-rx, hatY + ry * 0.14);
  ctx.lineTo(rx, hatY + ry * 0.14);
  ctx.stroke();

  // Wide white badge so "LPG 3KG" fits cleanly with padding
  fillRoundRect(ctx, -rx * 0.66, hatY - ry * 0.27, rx * 1.32, ry * 0.44, 6, "#FFFFFF", "#1E293B", 1.5);
  ctx.fillStyle = "#0F172A";
  ctx.font = "bold " + Math.round(headRadius * 0.40) + "px sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText("LPG 3KG", 0, hatY - ry * 0.05);
  ctx.restore();

  // 3. Bottom dark rim resting on stickman's head
  fillRoundRect(ctx, -rx * 0.92, hatY + ry * 0.72, rx * 1.84, headRadius * 0.24, 5, "#36691C", "#1E293B", 2);

  ctx.restore();
}

function drawStickman(ctx, x, y, scale, opts) {
  const o = opts || {};
  const t = o.time || 0;
  const mood = o.mood || "happy";
  const role = o.role || "normal";
  const tool = o.tool || null;
  const walkSpeed = o.walk || 0;
  const actionSwing = o.swing || 0;
  const multiArms = o.multiArms || 0;

  ctx.save();
  ctx.translate(x, y);
  ctx.scale(scale, scale);

  const headR = 30;
  const neckY = -125;
  const hipY = -48;
  const headY = -162 + Math.sin(t * 4) * 2.5;

  // Shadow on floor
  ctx.fillStyle = rgba(2, 6, 23, 0.4);
  ctx.beginPath();
  ctx.ellipse(0, 6, 42, 11, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  const limbColor = "#F8FAFC";

  // Legs
  const legSwing = walkSpeed > 0 ? Math.sin(t * 8 * walkSpeed) * 22 : 0;
  ctx.strokeStyle = limbColor;
  ctx.lineWidth = 9;

  ctx.beginPath();
  ctx.moveTo(0, hipY);
  ctx.lineTo(-16 + legSwing * 0.5, -24);
  ctx.lineTo(-20 + legSwing, 0);
  ctx.lineTo(-30 + legSwing, 0);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(0, hipY);
  ctx.lineTo(16 - legSwing * 0.5, -24);
  ctx.lineTo(20 - legSwing, 0);
  ctx.lineTo(30 - legSwing, 0);
  ctx.stroke();

  // Torso Spine
  ctx.beginPath();
  ctx.moveTo(0, neckY);
  ctx.lineTo(0, hipY);
  ctx.stroke();

  // Role Outfits
  if (role === "chef") {
    fillRoundRect(ctx, -18, neckY + 18, 36, 52, 6, "#F8FAFC", "#475569", 2);
    ctx.strokeStyle = PAL.lpgRed;
    ctx.lineWidth = 7;
    ctx.beginPath();
    ctx.moveTo(-15, neckY + 8);
    ctx.lineTo(0, neckY + 22);
    ctx.lineTo(15, neckY + 8);
    ctx.stroke();
  } else if (role === "prof") {
    fillRoundRect(ctx, -17, neckY + 12, 34, 48, 6, "#1E293B", PAL.ramGlow, 2);
    ctx.fillStyle = PAL.lpgGreen;
    ctx.beginPath();
    ctx.moveTo(0, neckY + 12);
    ctx.lineTo(-6, neckY + 42);
    ctx.lineTo(0, neckY + 50);
    ctx.lineTo(6, neckY + 42);
    ctx.closePath();
    ctx.fill();
  } else if (role === "artist") {
    fillRoundRect(ctx, -18, neckY + 15, 36, 48, 6, "#4C1D95", "#A78BFA", 2);
  }

  // Optional Multi-Arms for CPU Multi-Core turbo mode
  if (multiArms > 0) {
    ctx.save();
    for (let i = 0; i < multiArms; i++) {
      const side = i % 2 === 0 ? -1 : 1;
      const tier = Math.floor(i / 2);
      const ang = Math.sin(t * 14 + i * 1.3) * 0.55;
      const sy = neckY + 14 + tier * 14;
      ctx.strokeStyle = rgba(251, 191, 36, 0.55);
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.moveTo(0, sy);
      const ex = side * (36 + tier * 8) * Math.cos(ang * 0.5);
      const ey = sy - 12 + Math.sin(ang) * 24;
      const hx = ex + side * 28;
      const hy = ey + Math.cos(t * 14 + i) * 18;
      ctx.lineTo(ex, ey);
      ctx.lineTo(hx, hy);
      ctx.stroke();
    }
    ctx.restore();
  }

  // Main Arms
  ctx.strokeStyle = limbColor;
  ctx.lineWidth = 8.5;

  let lElbowX = -28, lElbowY = neckY + 26;
  let lHandX = -44, lHandY = neckY + 48;
  let rElbowX = 28, rElbowY = neckY + 24;
  let rHandX = 48, rHandY = neckY + 10 + Math.sin(t * 6) * 8;

  if (mood === "stressed") {
    lElbowX = -38; lElbowY = headY + 10;
    lHandX = -24; lHandY = headY - 4;
    rElbowX = 38; rElbowY = headY + 10;
    rHandX = 24; rHandY = headY - 4;
  } else if (mood === "proud") {
    lElbowX = -30; lElbowY = neckY + 28;
    lHandX = -16; lHandY = neckY + 46;
    rElbowX = 32; rElbowY = neckY + 6;
    rHandX = 56; rHandY = neckY - 22 + Math.sin(t * 5) * 6;
  } else if (actionSwing !== 0) {
    const sw = Math.sin(t * 9) * actionSwing;
    rElbowX = 30; rElbowY = neckY + 18;
    rHandX = 54 + sw * 16; rHandY = neckY + 8 + Math.cos(t * 9) * 12;
    lElbowX = -28; lElbowY = neckY + 22;
    lHandX = -46 - sw * 10; lHandY = neckY + 16;
  }

  ctx.beginPath();
  ctx.moveTo(0, neckY + 8);
  ctx.lineTo(lElbowX, lElbowY);
  ctx.lineTo(lHandX, lHandY);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(0, neckY + 8);
  ctx.lineTo(rElbowX, rElbowY);
  ctx.lineTo(rHandX, rHandY);
  ctx.stroke();

  // Held Tools in Right Hand
  if (tool === "screwdriver") {
    ctx.save();
    ctx.translate(rHandX, rHandY);
    ctx.rotate(-0.4 + Math.sin(t * 5) * 0.15);
    ctx.strokeStyle = "#94A3B8";
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(0, -34);
    ctx.stroke();
    fillRoundRect(ctx, -6, -8, 12, 22, 4, PAL.lpgRed, "#1E293B", 1.5);
    ctx.restore();
  } else if (tool === "magnifying") {
    ctx.save();
    ctx.translate(rHandX, rHandY);
    ctx.rotate(0.3);
    ctx.strokeStyle = "#FBBF24";
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(0, -18);
    ctx.stroke();
    ctx.fillStyle = rgba(56, 189, 248, 0.35);
    ctx.beginPath();
    ctx.arc(0, -34, 16, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.restore();
  } else if (tool === "spatula") {
    ctx.save();
    ctx.translate(rHandX, rHandY);
    ctx.rotate(-0.3 + Math.sin(t * 10) * 0.25);
    ctx.strokeStyle = "#E2E8F0";
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(0, -28);
    ctx.stroke();
    fillRoundRect(ctx, -9, -44, 18, 16, 3, "#CBD5E1", "#475569", 1.5);
    ctx.restore();
  } else if (tool === "paintbrush") {
    ctx.save();
    ctx.translate(rHandX, rHandY);
    ctx.rotate(-0.4 + Math.sin(t * 12) * 0.3);
    ctx.strokeStyle = "#F59E0B";
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(0, 6);
    ctx.lineTo(0, -24);
    ctx.stroke();
    ctx.fillStyle = PAL.gpuGlow;
    ctx.beginPath();
    ctx.arc(0, -29, 7, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  } else if (tool === "gamepad") {
    fillRoundRect(ctx, rHandX - 18, rHandY - 8, 32, 18, 6, "#38BDF8", "#0F172A", 2);
  }

  // Stickman Head Circle
  ctx.fillStyle = "#F8FAFC";
  ctx.strokeStyle = "#0F172A";
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(0, headY, headR, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();

  const eyeY = headY + 4;
  ctx.fillStyle = "#0F172A";
  ctx.strokeStyle = "#0F172A";
  ctx.lineWidth = 2.8;

  if (mood === "stressed" || mood === "dizzy") {
    ctx.beginPath();
    ctx.arc(-10, eyeY, 4, 0, Math.PI * 2);
    ctx.arc(10, eyeY, 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(0, eyeY + 15, 7, Math.PI, 0, false);
    ctx.stroke();
    ctx.fillStyle = "#38BDF8";
    ctx.beginPath();
    ctx.arc(headR + 8, headY + 4 + (t * 25) % 14, 4.5, 0, Math.PI * 2);
    ctx.fill();
  } else {
    ctx.beginPath();
    ctx.arc(-10, eyeY, 3.6, 0, Math.PI * 2);
    ctx.arc(10, eyeY, 3.6, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(0, eyeY + 8, 8, 0.15 * Math.PI, 0.85 * Math.PI, false);
    ctx.stroke();
  }

  if (role === "prof") {
    ctx.strokeStyle = "#0284C7";
    ctx.lineWidth = 3;
    fillRoundRect(ctx, -20, eyeY - 7, 16, 13, 3, rgba(56, 189, 248, 0.22), "#0284C7", 2.5);
    fillRoundRect(ctx, 4, eyeY - 7, 16, 13, 3, rgba(56, 189, 248, 0.22), "#0284C7", 2.5);
    ctx.beginPath();
    ctx.moveTo(-4, eyeY - 1);
    ctx.lineTo(4, eyeY - 1);
    ctx.stroke();
  }

  // Iconic 3kg Green Gas LPG Melon Hat on top of head
  const hatTilt = Math.sin(t * 3) * 0.04;
  drawLpgHat(ctx, 0, headY, headR, hatTilt);

  ctx.restore();
}

// ============================================================================
// REALISTIC PC HARDWARE COMPONENT DRAWINGS
// ============================================================================
function drawCpuComponent(ctx, cx, cy, scale, t, opts) {
  const o = opts || {};
  const showCores = o.showCores !== false;
  const activeCount = o.activeCores || 8;
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  fillRoundRect(ctx, -125, -125, 250, 250, 20, "#0F5132", "#34D399", 3);

  ctx.fillStyle = "#FBBF24";
  for (let i = -95; i <= 95; i += 19) {
    ctx.fillRect(i - 5, -118, 10, 8);
    ctx.fillRect(i - 5, 110, 10, 8);
    ctx.fillRect(-118, i - 5, 8, 10);
    ctx.fillRect(110, i - 5, 8, 10);
  }

  ctx.beginPath();
  ctx.moveTo(-116, 96);
  ctx.lineTo(-96, 116);
  ctx.lineTo(-116, 116);
  ctx.closePath();
  ctx.fill();

  const ihsGrad = ctx.createLinearGradient(-95, -95, 95, 95);
  ihsGrad.addColorStop(0, "#E2E8F0");
  ihsGrad.addColorStop(0.5, "#94A3B8");
  ihsGrad.addColorStop(1, "#CBD5E1");
  fillRoundRect(ctx, -96, -96, 192, 192, 18, ihsGrad, "#475569", 3);

  if (showCores) {
    fillRoundRect(ctx, -74, -64, 148, 112, 10, "#0F172A", PAL.cpuMain, 2.5);
    const cols = 4;
    const rows = 2;
    const cw = 28;
    const ch = 38;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const idx = r * cols + c;
        const kx = -60 + c * 33;
        const ky = -52 + r * 48;
        const pulse = 0.55 + 0.45 * Math.sin(t * 10 + idx * 0.9);
        const isOn = idx < activeCount;
        fillRoundRect(
          ctx,
          kx,
          ky,
          cw,
          ch,
          5,
          isOn ? rgba(245, 158, 11, pulse) : "#1E293B",
          isOn ? "#FEF08A" : "#475569",
          1.8
        );
      }
    }
    ctx.fillStyle = "#0F172A";
    ctx.font = "bold 17px sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("CPU MULTI-CORE", 0, 72);
  } else {
    ctx.fillStyle = "#0F172A";
    ctx.font = "bold 30px sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("CPU", 0, -14);
    ctx.font = "bold 16px sans-serif";
    ctx.fillStyle = "#334155";
    ctx.fillText("PROCESSOR", 0, 20);
  }

  ctx.restore();
}

function drawRamStick(ctx, cx, cy, scale, t, labelText, fillRatio) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const w = 360;
  const h = 105;

  ctx.fillStyle = "#FBBF24";
  for (let x = -w / 2 + 16; x < w / 2 - 16; x += 11) {
    if (Math.abs(x - 18) < 10) continue;
    ctx.fillRect(x, h / 2 - 6, 7, 18);
  }

  const pcbGrad = ctx.createLinearGradient(-w / 2, -h / 2, w / 2, h / 2);
  pcbGrad.addColorStop(0, "#0E7490");
  pcbGrad.addColorStop(1, "#155E75");
  fillRoundRect(ctx, -w / 2, -h / 2, w, h, 10, pcbGrad, PAL.ramGlow, 2.5);

  const activeW = (w - 24) * clamp(fillRatio !== undefined ? fillRatio : 0.75, 0.1, 1);
  fillRoundRect(ctx, -w / 2 + 12, -h / 2 + 8, w - 24, 12, 5, "#0F172A", null, 0);
  fillRoundRect(
    ctx,
    -w / 2 + 12,
    -h / 2 + 8,
    activeW,
    12,
    5,
    fillRatio > 0.9 ? PAL.danger : PAL.ramGlow,
    null,
    0
  );

  for (let i = 0; i < 8; i++) {
    const ix = -w / 2 + 18 + i * 41;
    const iy = -h / 2 + 28;
    const glow = 0.4 + 0.6 * Math.sin(t * 8 + i);
    fillRoundRect(ctx, ix, iy, 32, 56, 4, "#0F172A", rgba(56, 189, 248, glow), 1.8);
  }

  if (labelText) {
    fillRoundRect(ctx, -85, -14, 170, 32, 8, rgba(15, 23, 42, 0.92), PAL.ramGlow, 1.5);
    ctx.fillStyle = "#F8FAFC";
    ctx.font = "bold 17px sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(labelText, 0, 2);
  }

  ctx.restore();
}

function drawGpuCard(ctx, cx, cy, scale, t, fanSpeed) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const w = 390;
  const h = 156;

  ctx.strokeStyle = "#D97706";
  ctx.lineWidth = 7;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(-w / 2 + 40, -h / 2 - 6 - i * 6);
    ctx.lineTo(w / 2 - 40, -h / 2 - 6 - i * 6);
    ctx.stroke();
  }

  ctx.fillStyle = "#FBBF24";
  fillRoundRect(ctx, -w / 2 + 55, h / 2 - 4, 185, 18, 4, "#FBBF24", "#B45309", 1.5);
  fillRoundRect(ctx, -w / 2 - 14, -h / 2 - 10, 16, h + 28, 4, "#CBD5E1", "#64748B", 2);

  const shroudGrad = ctx.createLinearGradient(-w / 2, -h / 2, w / 2, h / 2);
  shroudGrad.addColorStop(0, "#1E293B");
  shroudGrad.addColorStop(1, "#0F172A");
  fillRoundRect(ctx, -w / 2, -h / 2, w, h, 18, shroudGrad, PAL.gpuMain, 3);

  ctx.strokeStyle = PAL.gpuGlow;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(-w / 2 + 24, -h / 2 + 12);
  ctx.lineTo(w / 2 - 24, -h / 2 + 12);
  ctx.moveTo(-w / 2 + 24, h / 2 - 12);
  ctx.lineTo(w / 2 - 24, h / 2 - 12);
  ctx.stroke();

  const fanCenters = [-122, 0, 122];
  const spd = fanSpeed !== undefined ? fanSpeed : 9;
  for (let f = 0; f < 3; f++) {
    const fx = fanCenters[f];
    ctx.save();
    ctx.translate(fx, 0);

    ctx.beginPath();
    ctx.arc(0, 0, 52, 0, Math.PI * 2);
    ctx.fillStyle = "#090D16";
    ctx.fill();
    ctx.lineWidth = 2.5;
    ctx.strokeStyle = PAL.gpuMain;
    ctx.stroke();

    ctx.rotate(t * spd + f * 1.1);
    ctx.strokeStyle = "#64748B";
    ctx.lineWidth = 6;
    for (let b = 0; b < 7; b++) {
      ctx.rotate((Math.PI * 2) / 7);
      ctx.beginPath();
      ctx.moveTo(8, 0);
      ctx.quadraticCurveTo(28, -14, 46, -4);
      ctx.stroke();
    }

    ctx.beginPath();
    ctx.arc(0, 0, 14, 0, Math.PI * 2);
    ctx.fillStyle = PAL.gpuMain;
    ctx.fill();
    ctx.restore();
  }

  ctx.restore();
}

// ============================================================================
// SCENE 1 (0.0s - 10.0s): GAMING PC SMOOTH vs LAPTOP BROWSER LAG
// ============================================================================
function renderScene1(ctx, t) {
  drawTopHeader(ctx, "FENOMENA KOMPUTER", "Kenapa Ada PC Ngebut & Ada yang Lag?", PAL.ramGlow);

  // TOP CARD: High-End Gaming PC (Y: 220 -> 950)
  drawCard(ctx, 60, 220, 960, 730, PAL.gpuMain, "PC GAMING • GRAFIS MEMUKAU (144 FPS)");
  ctx.save();
  roundedRectPath(ctx, 60, 220, 960, 730, 28);
  ctx.clip();

  fillRoundRect(ctx, 90, 820, 900, 22, 8, "#334155", null, 0);

  fillRoundRect(ctx, 510, 660, 60, 160, 8, "#475569", null, 0);
  fillRoundRect(ctx, 450, 804, 180, 18, 6, "#64748B", null, 0);
  fillRoundRect(ctx, 320, 330, 440, 290, 18, "#0F172A", PAL.gpuGlow, 4);

  ctx.save();
  roundedRectPath(ctx, 332, 342, 416, 266, 12);
  ctx.clip();
  const skyG = ctx.createLinearGradient(332, 342, 332, 608);
  skyG.addColorStop(0, "#064E3B");
  skyG.addColorStop(0.55, "#0F172A");
  skyG.addColorStop(1, "#047857");
  ctx.fillStyle = skyG;
  ctx.fillRect(332, 342, 416, 266);

  ctx.strokeStyle = rgba(52, 211, 153, 0.45);
  ctx.lineWidth = 2;
  for (let i = -5; i <= 5; i++) {
    ctx.beginPath();
    ctx.moveTo(540 + i * 20, 470);
    ctx.lineTo(540 + i * 95, 608);
    ctx.stroke();
  }
  const roadOffset = (t * 80) % 35;
  for (let y = 475 + roadOffset; y < 608; y += 35) {
    ctx.beginPath();
    ctx.moveTo(332, y);
    ctx.lineTo(748, y);
    ctx.stroke();
  }
  const shipX = 540 + Math.sin(t * 3.5) * 75;
  fillRoundRect(ctx, shipX - 36, 535, 72, 26, 8, PAL.gpuGlow, "#FFFFFF", 2);
  fillRoundRect(ctx, 348, 356, 130, 36, 8, rgba(15, 23, 42, 0.85), PAL.gpuGlow, 1.5);
  ctx.fillStyle = PAL.gpuGlow;
  ctx.font = "bold 20px sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText("144 FPS", 413, 374);
  ctx.restore();

  fillRoundRect(ctx, 800, 450, 150, 370, 16, "#0F172A", PAL.gpuMain, 3);
  for (let f = 0; f < 3; f++) {
    const fy = 515 + f * 95;
    ctx.beginPath();
    ctx.arc(875, fy, 36, 0, Math.PI * 2);
    ctx.strokeStyle = f === 0 ? PAL.cpuGlow : f === 1 ? PAL.ramGlow : PAL.gpuGlow;
    ctx.lineWidth = 4;
    ctx.stroke();
  }

  drawStickman(ctx, 195, 820, 1.45, {
    time: t,
    mood: "happy",
    tool: "gamepad",
    swing: 0.4
  });
  ctx.restore();

  // BOTTOM CARD: Lagging Laptop on Browser Tabs (Y: 990 -> 1740)
  drawCard(ctx, 60, 990, 960, 750, PAL.danger, "LAPTOP KENTANG • BUKA TAB LANGSUNG LAG!");
  ctx.save();
  roundedRectPath(ctx, 60, 990, 960, 750, 28);
  ctx.clip();

  fillRoundRect(ctx, 90, 1610, 900, 22, 8, "#334155", null, 0);

  const shakeX = Math.sin(t * 45) * 5;
  const shakeY = Math.cos(t * 38) * 4;
  for (let i = 0; i < 4; i++) {
    const tx = 350 + i * 32 + shakeX;
    const ty = 1105 + i * 28 + shakeY;
    fillRoundRect(ctx, tx, ty, 450, 220, 14, "#1E293B", PAL.danger, 2.5);
    fillRoundRect(ctx, tx, ty, 450, 42, 14, "#334155", null, 0);
    ctx.fillStyle = PAL.danger;
    ctx.beginPath();
    ctx.arc(tx + 24, ty + 21, 7, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#F8FAFC";
    ctx.font = "bold 18px sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    ctx.fillText("Tab Browser #" + (i + 1) + " (Not Responding...)", tx + 46, ty + 21);
  }

  ctx.save();
  ctx.translate(670 + shakeX, 1315 + shakeY);
  ctx.rotate(Math.floor(t * 4) * 0.9);
  ctx.strokeStyle = PAL.danger;
  ctx.lineWidth = 7;
  ctx.beginPath();
  ctx.arc(0, 0, 34, 0, Math.PI * 1.4);
  ctx.stroke();
  ctx.restore();

  fillRoundRect(ctx, 430 + shakeX, 1470, 260, 130, 10, "#334155", PAL.danger, 3);
  fillRoundRect(ctx, 390, 1594, 340, 18, 6, "#64748B", null, 0);

  for (let s = 0; s < 4; s++) {
    const prog = ((t * 0.8 + s * 0.25) % 1);
    const sx = 520 + Math.sin(t * 3 + s * 2) * 45;
    const sy = 1460 - prog * 130;
    ctx.fillStyle = rgba(244, 63, 94, (1 - prog) * 0.45);
    ctx.beginPath();
    ctx.arc(sx, sy, 16 + prog * 26, 0, Math.PI * 2);
    ctx.fill();
  }

  drawStickman(ctx, 210, 1610, 1.45, {
    time: t,
    mood: "stressed"
  });

  fillRoundRect(ctx, 790, 1470, 175, 110, 16, rgba(15, 23, 42, 0.9), PAL.danger, 2);
  ctx.fillStyle = PAL.danger;
  ctx.font = "bold 32px sans-serif";
  ctx.textAlign = "center";
  ctx.fillText("4 FPS", 877, 1515);
  ctx.font = "bold 18px sans-serif";
  ctx.fillStyle = "#FDA4AF";
  ctx.fillText("SYSTEM FREEZE", 877, 1552);

  ctx.restore();
}

// ============================================================================
// SCENE 2 (10.0s - 23.0s): MOTHERBOARD & THE 3 MAIN BRAINS
// ============================================================================
function renderScene2(ctx, t) {
  drawTopHeader(ctx, "DI BALIK LAYAR", "Kerja Sama 3 Otak Utama Komputer", PAL.cpuMain);

  drawCard(ctx, 60, 220, 960, 840, PAL.cpuMain, "ARSITEKTUR MOTHERBOARD • 3 KOMPONEN INTI");
  ctx.save();
  roundedRectPath(ctx, 60, 220, 960, 840, 28);
  ctx.clip();

  fillRoundRect(ctx, 110, 300, 860, 710, 24, "#0D1F2D", "#1E3A5F", 3);

  const busPaths = [
    { x1: 340, y1: 500, x2: 730, y2: 500, col: PAL.ramGlow },
    { x1: 340, y1: 530, x2: 730, y2: 530, col: PAL.ramGlow },
    { x1: 340, y1: 560, x2: 340, y2: 830, col: PAL.gpuGlow },
    { x1: 340, y1: 830, x2: 540, y2: 830, col: PAL.gpuGlow }
  ];

  for (let i = 0; i < busPaths.length; i++) {
    const b = busPaths[i];
    ctx.strokeStyle = rgba(148, 163, 184, 0.28);
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.moveTo(b.x1, b.y1);
    ctx.lineTo(b.x2, b.y2);
    ctx.stroke();

    const p = (t * 1.4 + i * 0.3) % 1;
    const px = lerp(b.x1, b.x2, p);
    const py = lerp(b.y1, b.y2, p);
    ctx.fillStyle = b.col;
    ctx.beginPath();
    ctx.arc(px, py, 9, 0, Math.PI * 2);
    ctx.fill();
  }

  drawCpuComponent(ctx, 320, 505, 0.90, t, { showCores: true, activeCores: 8 });
  fillRoundRect(ctx, 180, 645, 280, 44, 12, rgba(15, 23, 42, 0.92), PAL.cpuMain, 2);
  ctx.fillStyle = PAL.cpuGlow;
  ctx.font = "bold 22px sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText("1. PROSESOR (CPU)", 320, 667);

  drawRamStick(ctx, 730, 450, 0.88, t, "DDR5 • CH A", 0.75);
  drawRamStick(ctx, 730, 575, 0.88, t + 0.5, "DDR5 • CH B", 0.65);
  fillRoundRect(ctx, 590, 645, 280, 44, 12, rgba(15, 23, 42, 0.92), PAL.ramMain, 2);
  ctx.fillStyle = PAL.ramGlow;
  ctx.font = "bold 22px sans-serif";
  ctx.fillText("2. MEMORI (RAM)", 730, 667);

  drawGpuCard(ctx, 540, 825, 0.98, t, 10);
  fillRoundRect(ctx, 370, 935, 340, 44, 12, rgba(15, 23, 42, 0.92), PAL.gpuMain, 2);
  ctx.fillStyle = PAL.gpuGlow;
  ctx.font = "bold 22px sans-serif";
  ctx.fillText("3. KARTU GRAFIS (VGA/GPU)", 540, 957);

  ctx.restore();

  drawCard(ctx, 60, 1090, 960, 650, PAL.lpgGreen, "SINERGI SPESIFIK • TIDAK BISA SALING MENGGANTIKAN");
  ctx.save();
  roundedRectPath(ctx, 60, 1090, 960, 650, 28);
  ctx.clip();

  fillRoundRect(ctx, 90, 1630, 900, 20, 8, "#334155", null, 0);

  drawStickman(ctx, 235, 1630, 1.50, {
    time: t,
    mood: "focused",
    tool: "magnifying",
    swing: 0.3
  });

  const roles = [
    { title: "CPU • LOGIKA & INSTRUKSI", sub: "Otak Pengatur Strategi", y: 1230, col: PAL.cpuMain },
    { title: "RAM • RUANG KERJA INSTAN", sub: "Penampung Data Sementara", y: 1380, col: PAL.ramMain },
    { title: "VGA / GPU • MESIN VISUAL", sub: "Spesialis Render Grafis", y: 1530, col: PAL.gpuMain }
  ];

  for (let i = 0; i < roles.length; i++) {
    const r = roles[i];
    const appear = easeOutBack(sceneProgress(t, 11 + i * 2.0, 12.8 + i * 2.0));
    ctx.save();
    ctx.translate(665, r.y);
    ctx.scale(appear, appear);
    fillRoundRect(ctx, -255, -50, 510, 100, 18, "#0F172A", r.col, 3);
    ctx.fillStyle = r.col;
    ctx.font = "bold 23px sans-serif";
    ctx.textAlign = "left";
    ctx.fillText(r.title, -220, -12);
    ctx.fillStyle = "#CBD5E1";
    ctx.font = "20px sans-serif";
    ctx.fillText(r.sub, -220, 22);
    ctx.restore();
  }

  ctx.restore();
}

// ============================================================================
