  ctx.fillStyle = PAL.ramGlow;
  ctx.font = "bold 20px sans-serif";
  ctx.fillText("2. MEJA KERJA", 540, 1532);
  ctx.fillStyle = "#CBD5E1";
  ctx.font = "18px sans-serif";
